import{_ as p,W as o,s as r,u as d,ah as l,I as n,w as t,Z as i,A as s}from"./chunks/framework.CW1q-D1p.js";import"./chunks/theme.DKZ8RGYq.js";const y=JSON.parse('{"title":"如何在 Linux 中找到一个进程 ID 并杀死它 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中找到一个进程 ID 并杀死它 | LCTT (202212) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中找到一个进程 ID 并杀死它 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中找到一个进程 ID 并杀死它 | LCTT (202212) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202212/20221207.0 ⭐️ How to Find a Process ID and Kill it in Linux [CLI & GUI]","title":"如何在 Linux 中找到一个进程 ID 并杀死它","tag":"202212"},"relativePath":"202212/20221207.0 ⭐️ How to Find a Process ID and Kill it in Linux [CLI & GUI].md","filePath":"[post].md"}'),u={name:"202212/20221207.0 ⭐️ How to Find a Process ID and Kill it in Linux [CLI & GUI].md"};function m(c,a,h,b,g,x){const e=o("Link");return d(),r("div",null,[a[18]||(a[18]=l('<h1 id="如何在-linux-中找到一个进程-id-并杀死它" tabindex="-1">如何在 Linux 中找到一个进程 ID 并杀死它 <a class="header-anchor" href="#如何在-linux-中找到一个进程-id-并杀死它" aria-label="Permalink to 如何在 Linux 中找到一个进程 ID 并杀死它">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202212/12/103939c8tv41t8391v6886.jpg" alt=""></p><blockquote><p>一个简单的教学展示，教你如何找到正在运行中的进程 ID 并杀死它，你可以使用终端或者 GUI，这个方法适用于各类 Linux 发行版。</p></blockquote><p>你的 Linux 系统中运行的应用可能会让你的电脑变慢，特别是你的电脑配置较低的时候。在 Linux （以及所有其他 OS）中，程序或者应用都携带一个特别的 PID （进程 ID）可供你简单地分辨它们。</p><p>然而，大部分 Linux 初学者用户并不知道如何在 Linux 中寻找运行中的进程并杀死它。在这篇指南中，我们将会解释用不同的方法以杀死 Linux 中的运行进程。这包括了使用终端和 GUI 的方法。</p><p>记住，你只应该杀死未响应的进程，或者你发现应用无法被正常关闭 （针对基于 GUI 的应用）。</p><h3 id="如何在-linux-中找到-pid-并杀掉它们" tabindex="-1">如何在 Linux 中找到 PID 并杀掉它们 <a class="header-anchor" href="#如何在-linux-中找到-pid-并杀掉它们" aria-label="Permalink to 如何在 Linux 中找到 PID 并杀掉它们">​</a></h3><p>在这一部分中，我们首先应该先学会如何找到运行进程的 PID，然后再学习用以杀掉它们的命令：</p><h4 id="找到正在运行中的进程" tabindex="-1">找到正在运行中的进程 <a class="header-anchor" href="#找到正在运行中的进程" aria-label="Permalink to 找到正在运行中的进程">​</a></h4><p>你可以使用命令 <code>top</code> 来列出所有正在进行中的进程和它们的 PID，以及其他细节。程序 <code>top</code> 在所有 Linux 发行版和所有基于 Unix 的系统中都是默认安装了的。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>top</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Top-program-output.jpg" alt="Top program output"></p><p>同样地，你可以执行命令 <code>ps</code> 附带额外选项来获取某个指定的进程的 PID。例如，你可以使用以下命令来获得 <code>firefox</code> 的 PID。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ps -el | grep -i firefox</span></span></code></pre></div><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Firefox-process-id-using-ps-command-example.jpg" alt="Firefox process id using ps command - example"></p><p>现在你已经找到 PID 了，让我们看看你该如何杀掉它。</p><h4 id="杀死运行中的进程" tabindex="-1">杀死运行中的进程 <a class="header-anchor" href="#杀死运行中的进程" aria-label="Permalink to 杀死运行中的进程">​</a></h4><p>使用以下命令，你可以通过进程的名字或者 PID 来杀掉这个正在运行中的进程：</p>',18)),n("ul",null,[a[2]||(a[2]=n("li",null,[n("code",null,"killall"),t("：通过运行进程的名字来杀死进程")],-1)),n("li",null,[i(e,{href:"https://linux.die.net/man/1/kill"},{default:s(()=>a[0]||(a[0]=[t("kill")])),_:1}),a[1]||(a[1]=t("：通过 PID 来杀死进程"))])]),a[19]||(a[19]=l('<p>现在，让我们首先使用进程 <code>killall</code> 通过 Firefox 这个名字来杀死它的，命令如下：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>killall -9 firefox</span></span></code></pre></div><ul><li>参数 <code>-9</code> 发送了信号 <code>SIGKILL</code> 通知 OS 来终止这个进程。</li><li>使用以下命令，你也可以列出一些别的信号。</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -l</span></span></code></pre></div><p>同样地，如果你想要通过 PID 来杀死进程，你可以用以下命令：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -9 &lt;PID&gt;</span></span></code></pre></div><p>在这个例子中，命令会长这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>kill -9 33665</span></span></code></pre></div><p>让我们看看在不同发行版中，你该如何使用图形用户界面（GUI）来杀死任意进程或应用。</p><h3 id="通过-gui-寻找-pid-并杀掉" tabindex="-1">通过 GUI 寻找 PID 并杀掉 <a class="header-anchor" href="#通过-gui-寻找-pid-并杀掉" aria-label="Permalink to 通过 GUI 寻找 PID 并杀掉">​</a></h3><p>现在有很多图形界面程序可以枚列进程。大部分 Linux 发行版的桌面环境中已经携带了它们。我们在这里列举出了一些。</p><h4 id="gnome-在-ubuntu、fedora-工作站等-在-linux-mint-中" tabindex="-1">GNOME（在 Ubuntu、Fedora 工作站等） &amp; 在 Linux Mint 中 <a class="header-anchor" href="#gnome-在-ubuntu、fedora-工作站等-在-linux-mint-中" aria-label="Permalink to GNOME（在 Ubuntu、Fedora 工作站等） &amp; 在 Linux Mint 中">​</a></h4><p>在应用菜单中搜索 “system monitor” 并打开它（LCTT 译注：中文桌面环境也可以搜 “system monitor”，我在 Ubuntu 里试过了）。在 “<ruby>进程<rt>Processes</rt></ruby>” 标签页下找到你的进程，右击进程名字打开快捷菜单，选择选项 “<ruby>杀死<rt>Kill</rt></ruby>”。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Kill-a-process-in-Linux-using-gnome-system-monitor.jpg" alt="Kill a process in Linux using gnome system monitor"></p><h4 id="kde-plasma-kubuntu、fedora-kde-或任何基于-plasma-的发行版" tabindex="-1">KDE Plasma（Kubuntu、Fedora-KDE 或任何基于 Plasma 的发行版） <a class="header-anchor" href="#kde-plasma-kubuntu、fedora-kde-或任何基于-plasma-的发行版" aria-label="Permalink to KDE Plasma（Kubuntu、Fedora-KDE 或任何基于 Plasma 的发行版）">​</a></h4><p>在应用菜单中搜索并启动 “system monitor”。这会打开以下程序。在左边菜单栏点击“<ruby>进程<rt>Processes</rt></ruby>” ，你因该能看见一列正在运行的程序。你可以右击列表里的进程或应用并选择“<ruby>杀死<rt>Kill</rt></ruby>”来终止进程。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/System-monitor-in-KDE-Plasma.jpg" alt="System monitor in KDE Plasma"></p><h4 id="xfce-桌面" tabindex="-1">Xfce 桌面 <a class="header-anchor" href="#xfce-桌面" aria-label="Permalink to Xfce 桌面">​</a></h4><p>Xfce 桌面可以完成这项任务的原生应用是 <ruby>任务管理器<rt>Task Manager</rt></ruby>，你可以通过 “<ruby>应用<rt>Application</rt></ruby> &gt; <ruby>系统<rt>System</rt></ruby> &gt; <ruby>任务管理器<rt>Task manager</rt></ruby>” 来找到它。右击进程名字然后选择“<ruby>杀死<rt>Kill</rt></ruby>”来终止应用或进程。</p><p><img src="https://www.debugpoint.com/wp-content/uploads/2022/12/Xfce-task-manager-to-kill-a-process.jpg" alt="Xfce task manager to kill a process"></p><h4 id="如何在其他桌面或发行版上杀死一个进程或程序" tabindex="-1">如何在其他桌面或发行版上杀死一个进程或程序 <a class="header-anchor" href="#如何在其他桌面或发行版上杀死一个进程或程序" aria-label="Permalink to 如何在其他桌面或发行版上杀死一个进程或程序">​</a></h4><p>如果你找不到任何相似的程序，你可以选择使用终端的方法。或者，你可以使用以下命令来安装 gnome-system-monitor。</p><p>Ubuntu 以及相关发行版：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo apt install gnome-system-monitor</span></span></code></pre></div><p>Fedora 以及其相关的发行版：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo dnf install gnome-system-monitor</span></span></code></pre></div><p>还有 Arch Linux：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sudo pacman -S gnome-system-monitor</span></span></code></pre></div><h3 id="总结一下" tabindex="-1">总结一下 <a class="header-anchor" href="#总结一下" aria-label="Permalink to 总结一下">​</a></h3><p>这就是你该如何在 Linux 中找到一个运行中的进程的 PID 并杀死它。我们已经解释了不同的方法：你可以通过名字或者 PID 来杀死进程。我希望这对你有所帮助。</p><hr>',31)),n("p",null,[a[4]||(a[4]=t("via: ")),i(e,{href:"https://www.debugpoint.com/find-process-id-kill-linux/"},{default:s(()=>a[3]||(a[3]=[t("https://www.debugpoint.com/find-process-id-kill-linux/")])),_:1})]),n("p",null,[a[9]||(a[9]=t("作者：")),i(e,{href:"https://www.debugpoint.com/author/admin1/"},{default:s(()=>a[5]||(a[5]=[t("Arindam")])),_:1}),a[10]||(a[10]=t(" 选题：")),i(e,{href:"https://github.com/lkxed"},{default:s(()=>a[6]||(a[6]=[t("lkxed")])),_:1}),a[11]||(a[11]=t(" 译者：")),i(e,{href:"https://github.com/yzuowei"},{default:s(()=>a[7]||(a[7]=[t("yzuowei")])),_:1}),a[12]||(a[12]=t(" 校对：")),i(e,{href:"https://github.com/wxy"},{default:s(()=>a[8]||(a[8]=[t("wxy")])),_:1})]),n("p",null,[a[15]||(a[15]=t("本文由 ")),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>a[13]||(a[13]=[t("LCTT")])),_:1}),a[16]||(a[16]=t(" 原创编译，")),i(e,{href:"https://linux.cn/"},{default:s(()=>a[14]||(a[14]=[t("Linux中国")])),_:1}),a[17]||(a[17]=t(" 荣誉推出"))])])}const v=p(u,[["render",m]]);export{y as __pageData,v as default};
